package com.hostelfind.controller;
import com.hostelfind.dto.*; import com.hostelfind.model.*; import com.hostelfind.service.ItemService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/items") @CrossOrigin(origins="*") public class ItemController { private final ItemService service; public ItemController(ItemService s){service=s;} @GetMapping public List<ItemResponse> all(@RequestParam(required=false) String q,@RequestParam(required=false) String category,@RequestParam(required=false) ItemType type){return service.publicItems(q,category,type).stream().map(service::publicView).toList();}@GetMapping("/{id}") public ItemResponse one(@PathVariable Long id){return service.publicView(service.one(id));}@PostMapping public ResponseEntity<Item> create(@Valid @RequestBody ItemRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@PutMapping("/{id}") public Item update(@PathVariable Long id,@Valid @RequestBody ItemRequest r){return service.update(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);} }
